<script lang="ts">
	import { onMount } from 'svelte';
	import { request } from './api';
	import { AlertBanner, PageHeader } from './ui';
	const reports=[
		{key:'attendance',title:'Presensi',description:'Check-in, check-out, dan status presensi hingga 10.000 baris terbaru.',path:'/v1/reports/attendance.csv',file:'attendance-report.csv'},
		{key:'payroll',title:'Payroll',description:'Rekap net amount karyawan berdasarkan periode payroll.',path:'/v1/reports/payroll.csv',file:'payroll-report.csv'},
		{key:'leave',title:'Cuti',description:'Riwayat pengajuan cuti, tanggal, status, dan alasan.',path:'/v1/reports/leave.csv',file:'leave-report.csv'},
		{key:'accounting',title:'Buku besar',description:'Baris jurnal posted dengan akun debit dan kredit.',path:'/v1/reports/accounting.csv',file:'accounting-ledger.csv'}
	];
	type Schedule={id:string;report_key:string;format:string;frequency:string;recipient_email:string;is_active:boolean};
	let downloading=$state(''),error=$state(''),schedules=$state<Schedule[]>([]),recipientEmail=$state(''),reportKey=$state('attendance'),format=$state('csv'),frequency=$state('weekly'),saving=$state(false);
	async function loadSchedules(){try{schedules=await request<Schedule[]>('/v1/reports/schedules');}catch(cause){error=cause instanceof Error?cause.message:'Jadwal laporan tidak dapat dimuat.';}}
	async function schedule(){saving=true;error='';try{await request('/v1/reports/schedules',{method:'POST',body:JSON.stringify({report_key:reportKey,format,frequency,recipient_email:recipientEmail})});recipientEmail='';await loadSchedules();}catch(cause){error=cause instanceof Error?cause.message:'Jadwal laporan tidak dapat disimpan.';}finally{saving=false;}}
	onMount(()=>void loadSchedules());
	async function download(path:string,file:string){downloading=path;error='';try{const response=await fetch(path,{credentials:'include'});if(!response.ok)throw new Error('Ekspor gagal disiapkan.');const url=URL.createObjectURL(await response.blob());const anchor=document.createElement('a');anchor.href=url;anchor.download=file;anchor.click();URL.revokeObjectURL(url);}catch(cause){error=cause instanceof Error?cause.message:'Ekspor gagal.';}finally{downloading='';}}
</script>
<main class="workspace-page reports-page"><PageHeader title="Reports" description="Ekspor data native server-side; laporan tidak perlu dimuat penuh ke browser." backHref="/admin/dashboard"/>{#if error}<AlertBanner title="Ekspor belum tersedia" message={error}/>{/if}<section class="panel"><div class="intro"><h2>Pusat ekspor</h2><p>CSV dapat dibuka di Excel, Google Sheets, atau perangkat akuntansi.</p></div><div class="report-grid">{#each reports as report}<article><div><h3>{report.title}</h3><p>{report.description}</p></div><div class="download-actions"><button class="quiet" disabled={Boolean(downloading)} onclick={()=>void download(report.path,report.file)}>{downloading===report.path?'Menyiapkan…':'CSV'}</button><button class="quiet" disabled={Boolean(downloading)} onclick={()=>void download(`/v1/reports/${report.key}.pdf`,`${report.key}-report.pdf`)}>{downloading===`/v1/reports/${report.key}.pdf`?'Menyiapkan…':'PDF'}</button></div></article>{/each}</div></section><section class="panel"><h2>Jadwalkan laporan</h2><form novalidate onsubmit={(event)=>{event.preventDefault();void schedule();}}><select bind:value={reportKey}>{#each reports as report}<option value={report.key}>{report.title}</option>{/each}</select><select bind:value={format}><option value="csv">CSV</option><option value="pdf">PDF</option></select><select bind:value={frequency}><option value="daily">Harian</option><option value="weekly">Mingguan</option><option value="monthly">Bulanan</option></select><input type="email" bind:value={recipientEmail} required placeholder="penerima@perusahaan.com"/><button disabled={saving}>{saving?'Menyimpan…':'Simpan jadwal'}</button></form>{#each schedules as item(item.id)}<p class="schedule">{item.report_key} · {item.format.toUpperCase()} · {item.frequency} → {item.recipient_email}</p>{/each}</section></main>
<style>.reports-page{display:grid;gap:12px}.panel{padding:14px;border-radius:var(--radius)}h2,h3{margin:0;color:var(--ink)}h2{font-size:14px}h3{font-size:13px}.intro p,article p{color:var(--muted);font-size:12px;line-height:1.5}.report-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;margin-top:12px}article{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px;border:1px solid var(--line);border-radius:var(--radius-sm);background:var(--surface-alt)}article p{margin:4px 0 0}@media(max-width:680px){.report-grid{grid-template-columns:1fr}article{align-items:flex-start;flex-direction:column}}</style>
